'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const owl = cls => `<svg class="${cls}" aria-hidden="true"><use href="#owl"/></svg>`;
const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY = 'novarge-progress-v1';
const alphabet = [...'ELAKİNOMUTÜYÖRIDSBZÇGCPHĞVFŞJ'];
const allLetters = [...new Set([...alphabet, ...'ABCÇDEFGĞHIİJKLMNOÖPRSŞTUÜVYZ'])];
const fresh = () => ({name:'Minik kaşif', completed:[], activityLog:[], sound:true, dailyGoal:3});
let state = fresh(), storageAvailable = true;
try { const saved = JSON.parse(localStorage.getItem(KEY)); if (saved && Array.isArray(saved.completed)) state = {...fresh(), ...saved, completed:saved.completed.filter(v => typeof v === 'string'), activityLog:Array.isArray(saved.activityLog) ? saved.activityLog : []}; } catch { storageAvailable = false; }
let page = 'home', modalCleanup = () => {}, recognition = null, micAllowed = false, toastTimer;
let parentVerified = false, currentExercise = null;
const todayKey = () => new Date().toLocaleDateString('sv-SE');
const todayCount = () => state.activityLog.filter(x => x.date === todayKey()).length;
const tracedLetters = () => allLetters.filter(letter => state.completed.includes(`write:${letter}`));
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch { storageAvailable = false; toast('Bu tarayıcı ilerlemeyi kaydedemiyor. Bu oturumda devam edebilirsin.'); } updateCounters(); };
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 4500); }
function updateCounters() { $('#sideStars').textContent = state.completed.length; $('.profile b').textContent = state.name; $('#soundToggle').classList.toggle('muted', !state.sound); $('#soundToggle').setAttribute('aria-pressed', String(state.sound)); $('#soundToggle').setAttribute('aria-label', state.sound ? 'Sesli yönlendirmeyi kapat' : 'Sesli yönlendirmeyi aç'); }
function celebrate() { if (matchMedia('(prefers-reduced-motion: reduce)').matches) return; const colors=['#d5aa50','#8daf7b','#cf8056','#b0a1c7']; const holder=$('#confetti'); holder.replaceChildren(); for(let i=0;i<28;i++){const el=document.createElement('i');el.className='confetti-piece';el.style.cssText=`left:${Math.random()*100}%;background:${colors[i%4]};--drift:${Math.random()*170-85}px;animation-delay:${Math.random()*.3}s;`;holder.append(el);}setTimeout(()=>holder.replaceChildren(),2500); }
function award(id) { const isNew = !state.completed.includes(id); if (isNew) state.completed.push(id); state.activityLog.push({date:todayKey(), type:id.split(':')[0]}); state.activityLog = state.activityLog.slice(-500); save(); if(isNew) celebrate(); return isNew; }
function speak(text, {force=false, onEnd} = {}) {
  if (!state.sound && !force) { onEnd?.(); return false; }
  if (!('speechSynthesis' in window)) { toast('Bu cihaz sesli okumayı desteklemiyor. Etkinlikleri ekrandan takip edebilirsin.'); onEnd?.(); return false; }
  speechSynthesis.cancel(); const voices=speechSynthesis.getVoices(); const tr=voices.find(v=>v.lang.toLowerCase().startsWith('tr'));
  const utterance=new SpeechSynthesisUtterance(text);utterance.lang='tr-TR';utterance.rate=.78;utterance.pitch=1.05;if(tr)utterance.voice=tr;
  utterance.onend=()=>onEnd?.();utterance.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled'){toast('Ses çalınamadı. Cihazının Türkçe ses ve ses seviyesi ayarlarını kontrol et.');onEnd?.();}};
  speechSynthesis.speak(utterance);return true;
}
function feedback(message, type='') { const el=$('#feedback');if(el){el.textContent=message;el.className=`feedback ${type}`;} }
function cleanupActivity() { modalCleanup(); modalCleanup=()=>{}; currentExercise=null; if('speechSynthesis'in window)speechSynthesis.cancel(); if(recognition){recognition.abort();recognition=null;} }
function showActivity(label, html) { cleanupActivity(); $('#activityLabel').textContent=label; $('#activityBody').innerHTML=html; if(!$('#activity').open)$('#activity').showModal(); }
function closeActivity() { cleanupActivity(); $('#activity').close(); render(); }
$('#closeActivity').onclick=closeActivity;
$('#activity').addEventListener('cancel',cleanupActivity);
$('#activity').addEventListener('close',()=>{cleanupActivity();render();});
$('#soundToggle').onclick=()=>{state.sound=!state.sound;save();if(!state.sound && 'speechSynthesis'in window)speechSynthesis.cancel();toast(state.sound?'Sesli yönlendirme açık.':'Sesli yönlendirme kapalı. Dinle düğmeleri yine kullanılabilir.');};
$$('[data-nav]').forEach(btn=>btn.onclick=()=>navigate(btn.dataset.nav));
function navigate(target) { page=target;location.hash=target;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true}); }
window.addEventListener('hashchange',()=>{const target=location.hash.slice(1);if(['home','write','read','listen','rewards'].includes(target)){page=target;render();}});
function render() {
  const names={home:'Keşif alanım',write:'Harfleri çiz',read:'Birlikte okuyalım',listen:'Dinle ve söyle',rewards:'Yıldızlarım'};
  $('#pageName').textContent=names[page];$$('[data-nav]').forEach(el=>{el.classList.toggle('active',el.dataset.nav===page);el.setAttribute('aria-current',el.dataset.nav===page?'page':'false');});updateCounters();
  $('#main').innerHTML=({home:homePage,write:writePage,read:readPage,listen:listenPage,rewards:rewardsPage}[page]||homePage)();
  $$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));
  $$('[data-write]').forEach(b=>b.onclick=()=>openWrite(b.dataset.write));
  $$('[data-read]').forEach(b=>b.onclick=()=>openRead(b.dataset.read,0));
  $$('[data-listen]').forEach(b=>b.onclick=()=>b.dataset.listen==='speak'?openSpeak(0):openListen(0));
  $('#continueBtn')?.addEventListener('click',()=>openWrite(allLetters.find(l=>!state.completed.includes(`write:${l}`))||'E'));
}
function homePage() {
 const done=tracedLetters(), target=allLetters.find(l=>!done.includes(l))||'E', count=todayCount(), goal=state.dailyGoal;
 return `<section class="greeting"><div><h1>Merhaba, ${escapeHTML(state.name)}! <span aria-hidden="true">☀️</span></h1><p>Bugün birlikte neler keşfedeceğiz?</p></div><div class="day-chip"><span>✧</span> Öğrenmek için harika bir gün</div></section>
 <section class="hero"><div class="hero-copy"><span class="eyebrow">✦ OYUNLA ÖĞREN, KEYİFLE KEŞFET</span><h2>Küçük harfler,<br><span>büyük keşifler!</span></h2><p>Çizelim, dinleyelim, birlikte okuyalım.<br>Her harfle yepyeni bir dünyaya adım atalım.</p><button class="primary" id="continueBtn">${done.length?'Keşfe devam et':'Haydi, başlayalım'} ${icon('arrow')}</button><span class="hero-duration">◷ Kısa ve eğlenceli oyunlar</span></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="letter-float float-a">A</span><span class="letter-float float-e">E</span><span class="letter-float float-l">L</span><span class="spark spark-one">✧</span><span class="spark spark-two">✦</span>${owl('hero-owl')}</div></section>
 <div class="section-head"><div><h2>Bugünün keşifleri</h2><p>Biraz çizgi, biraz ses, bolca eğlence.</p></div><button class="text-link" data-go="write">Tüm harfler ${icon('arrow')}</button></div>
 <section class="learning-cards" aria-label="Öğrenme alanları"><button class="learn-card" data-go="write"><div class="card-top"><span class="activity-icon">${icon('pencil')}</span><span class="step">01 · YAZ</span></div><h3>Harfleri çiz</h3><p>Parmağınla izleri takip et,<br>harflerle tanış.</p><div class="card-bottom"><span>İlk durak: ${target} harfi</span><span class="round-arrow">${icon('arrow')}</span></div></button><button class="learn-card read-card" data-go="read"><div class="card-top"><span class="activity-icon">${icon('book')}</span><span class="step">02 · OKU</span></div><h3>Birlikte okuyalım</h3><p>Harfler birleşsin, kelimeler<br>ve cümleler oluşsun.</p><div class="card-bottom"><span>Harflerden hikâyelere</span><span class="round-arrow">${icon('arrow')}</span></div></button><button class="learn-card listen-card" data-go="listen"><div class="card-top"><span class="activity-icon">${icon('headphones')}</span><span class="step">03 · DİNLE</span></div><h3>Dinle ve söyle</h3><p>Sesleri keşfet, dikkatle dinle,<br>sen de söyle.</p><div class="card-bottom"><span>Seslerle oyun zamanı</span><span class="round-arrow">${icon('arrow')}</span></div></button></section>
 <section class="bottom-grid"><div class="journey"><div class="section-head"><h2>Harf yolculuğum</h2><span class="tiny-tag">${done.length} / 29 harf</span></div><p class="empty-note">Her harf, yeni bir başlangıç.</p><div class="letter-path">${allLetters.slice(0,6).map((l,i)=>`${i?'<span class="path-line"></span>':''}<button data-write="${l}" class="path-letter ${done.includes(l)?'complete':l===target?'current':''}" aria-label="${l} harfini çiz">${l}${done.includes(l)?'<small>✓</small>':''}</button>`).join('')}</div><div class="journey-footer"><div class="progress-track"><div class="progress-fill" style="width:${done.length/29*100}%"></div></div><span>Adım adım, birlikte</span></div></div><div class="daily"><div class="section-head"><h2>Bugünün minik hedefi</h2><span class="tiny-tag">${Math.min(count,goal)} / ${goal}</span></div><div class="daily-main"><span class="star-medal">${icon('star')}</span><div><h3>${count>=goal?'Bugünün yıldızı sensin!':`${goal} oyun, kocaman bir yıldız!`}</h3><p>${count>=goal?'Harika keşifler yaptın. Biraz dinlenelim.':'Her küçük çaban çok değerli.'}</p><div class="progress-track"><div class="progress-fill" style="width:${Math.min(count/goal*100,100)}%"></div></div></div></div><div class="daily-foot">✧ ${count>=goal?'Hedef tamamlandı. İstersen yine oynayabilirsin.':`Hedefine ${Math.max(goal-count,0)} oyun kaldı. Hazır mısın?`}</div></div></section>`;
}
function intro(title,desc,eyebrow){return `<section class="page-intro"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></section>`;}
function writePage(){return intro('Her harf bir keşif.','Bir harf seç, parmağınla ya da kaleminle üzerinden geç. İstersen küçük harfini de çiz!','01 · ÇİZEREK ÖĞREN')+`<div class="letter-grid">${allLetters.map(l=>`<button class="letter-tile" data-write="${l}" aria-label="${l} harfini çiz"><b>${l} <span style="font-size:25px">${l.toLocaleLowerCase('tr-TR')}</span></b><span>Çiz ve keşfet</span>${state.completed.includes('write:'+l)?'<small class="done-dot">★</small>':''}</button>`).join('')}</div><div class="info-strip">${icon('pencil')} Yavaşça çiz, şeklin üzerinden geç. Mükemmel olması gerekmiyor; birlikte deneyebiliriz.</div>`;}
function readPage(){return intro('Harfler el ele verince…','Önce heceler, sonra kelimeler, en sonunda kendi cümlelerin. Bir oyun seçelim!','02 · BİRLEŞTİREREK ÖĞREN')+`<div class="activity-cards"><button class="lesson-card" data-read="syllable"><span class="big-symbol">E + L</span><span class="pill">1. durak · Heceler</span><h2>Harfleri birleştir</h2><p>Harfleri sıraya koy, hecenin nasıl okunduğunu dinle.</p></button><button class="lesson-card" data-read="word"><span class="big-symbol">ELMA</span><span class="pill">2. durak · Kelimeler</span><h2>Kelime atölyesi</h2><p>Resme bak, heceleri birleştir ve kelimeni oluştur.</p></button><button class="lesson-card" data-read="sentence"><span class="big-symbol" style="font-size:31px">Ali top at.</span><span class="pill">3. durak · Cümleler</span><h2>İlk cümlem</h2><p>Kelimeleri sıraya koy. Cümleni birlikte okuyalım.</p></button></div><p class="info-strip" style="margin-top:25px">Her etkinliği istediğin kadar tekrarlayabilirsin. Bir harfte zorlanırsan çizme oyununa geri dönebilirsin.</p>`;}
function listenPage(){return intro('Kulak ver, sesini keşfet.','Dinleyelim, bulalım, birlikte söyleyelim. Her ses yeni bir oyun!','03 · DİNLEYEREK ÖĞREN')+`<div class="activity-cards"><button class="lesson-card" data-listen="find"><span class="big-symbol">${icon('headphones')}</span><span class="pill">Dinle ve bul</span><h2>Hangi kelime?</h2><p>Duyduğun kelimeye ait resmi seç. Dikkatli kulaklar iş başında!</p></button><button class="lesson-card" data-listen="speak"><span class="big-symbol">${icon('mic')}</span><span class="pill">Dinle ve söyle</span><h2>Sıra senin sesinde</h2><p>Kelimeyi dinle, sonra sen söyle. Bir büyüğünle başlayabilirsin.</p></button></div><p class="info-strip" style="margin-top:25px">Sesli okuma, cihazının Türkçe ses desteğini kullanır. Konuşma oyunu için ebeveyn alanında mikrofon kullanımını açabilirsin.</p>`;}
function rewardsPage(){const c=state.completed;const medals=[['🌱','İlk keşfim','İlk oyununu tamamla.',c.length>=1],['✍️','Harf kaşifi','3 farklı harfi çiz.',tracedLetters().length>=3],['📖','Kelime ustası','3 kelime oyunu tamamla.',c.filter(x=>x.startsWith('word:')).length>=3],['🎧','Dikkatli kulak','3 dinleme oyunu tamamla.',c.filter(x=>x.startsWith('listen:')).length>=3],['🌟','Parlayan yıldız','10 farklı oyunu tamamla.',c.length>=10],['💬','Cümle kurucusu','3 cümle oyunu tamamla.',c.filter(x=>x.startsWith('sentence:')).length>=3],['🌳','Harf ormanı','10 farklı harfi çiz.',tracedLetters().length>=10],['🦉','Bilge baykuş','29 harfin hepsini çiz.',tracedLetters().length>=29]];return intro('Küçük çabalar, büyük mutluluklar.','Her yeni etkinlikte bir yıldız kazan. Tekrar etmek de öğrenmenin bir parçası!','BENİM BAŞARILARIM')+`<div class="reward-summary"><span class="star-medal">${icon('star')}</span><div><strong>${c.length}</strong><p class="empty-note">Yolculuğunda topladığın yıldızlar</p></div></div><div class="reward-grid">${medals.map(([emoji,name,desc,earned])=>`<div class="reward ${earned?'':'locked'}"><span class="medal" aria-hidden="true">${emoji}</span><h3>${name}</h3><p>${desc}</p><span class="tiny-tag">${earned?'✓ Kazanıldı':'Keşfetmeye devam'}</span></div>`).join('')}</div>`;}

function openWrite(letter, lower=false) {
 const glyph=lower?letter.toLocaleLowerCase('tr-TR'):letter;
 showActivity('01 · HARFLERİ ÇİZ',`<div class="activity-heading"><h2 id="activityTitle">${glyph} harfini çizelim</h2><button id="hearLetter" class="secondary">${icon('sound')} Harfi dinle</button></div><p class="activity-sub">Açık renkli harfin üzerinden parmağınla geç. Harfin tamamını boyamaya çalış.</p><div style="display:flex;gap:8px;margin-bottom:12px"><button id="uppercase" class="secondary" ${!lower?'disabled':''}>${letter} · Büyük harf</button><button id="lowercase" class="secondary" ${lower?'disabled':''}>${letter.toLocaleLowerCase('tr-TR')} · Küçük harf</button></div><div class="canvas-wrap"><canvas id="traceCanvas" width="700" height="400" aria-label="${glyph} harfini çizme alanı. Dokunarak, kalemle veya fareyle çizin."></canvas><span class="canvas-label">PARMAĞIN YA DA KALEMİNLE ÇİZ</span></div><div class="tool-row"><button class="secondary" id="clearCanvas">↺ Yeniden çiz</button><button class="primary" id="checkTrace">Çizgimi kontrol et ${icon('check')}</button></div><p class="feedback" id="feedback" role="status">Birlikte deneyelim. Acelemiz yok.</p><p class="small-help">Çizim kontrolü, harfin üzerini ne kadar takip ettiğine bakar. Bir el yazısı veya gelişim değerlendirmesi değildir.</p>`);
 currentExercise=`write:${letter}${lower?':lower':''}`;
 $('#hearLetter').onclick=()=>speak(glyph,{force:true});$('#uppercase').onclick=()=>openWrite(letter);$('#lowercase').onclick=()=>openWrite(letter,true);
 const canvas=$('#traceCanvas'),ctx=canvas.getContext('2d'),w=700,h=400;let drawing=false,points=[],distance=0,last=null,finished=false;
 const mask=document.createElement('canvas');mask.width=w;mask.height=h;const mc=mask.getContext('2d',{willReadFrequently:true});
 const font=`800 ${lower?320:300}px Arial`;mc.font=font;mc.textAlign='center';mc.textBaseline='middle';mc.fillText(glyph,w/2,h/2+20);const md=mc.getImageData(0,0,w,h).data;
 const cells=new Set();for(let y=0;y<h;y+=8)for(let x=0;x<w;x+=8)if(md[(y*w+x)*4+3]>100)cells.add(`${Math.floor(x/12)},${Math.floor(y/12)}`);
 const redraw=()=>{ctx.clearRect(0,0,w,h);ctx.font=font;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#e4eadb';ctx.fillText(glyph,w/2,h/2+20);ctx.strokeStyle='#d1dcc5';ctx.lineWidth=1;ctx.strokeText(glyph,w/2,h/2+20);ctx.lineCap='round';ctx.lineJoin='round';};redraw();
 const position=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*w,y:(e.clientY-r.top)/r.height*h};};
 function addPoint(p){points.push(p);ctx.strokeStyle='#61946c';ctx.fillStyle='#61946c';ctx.lineWidth=25;if(last){ctx.beginPath();ctx.moveTo(last.x,last.y);ctx.lineTo(p.x,p.y);ctx.stroke();const d=Math.hypot(last.x-p.x,last.y-p.y);distance+=d;const steps=Math.ceil(d/5);for(let j=1;j<steps;j++)points.push({x:last.x+(p.x-last.x)*j/steps,y:last.y+(p.y-last.y)*j/steps});}else{ctx.beginPath();ctx.arc(p.x,p.y,12.5,0,Math.PI*2);ctx.fill();}last=p;}
 canvas.onpointerdown=e=>{if(finished)return;e.preventDefault();drawing=true;last=null;canvas.setPointerCapture(e.pointerId);addPoint(position(e));};
 canvas.onpointermove=e=>{if(!drawing)return;e.preventDefault();for(const event of e.getCoalescedEvents?.()||[e])addPoint(position(event));};
 const stop=()=>{drawing=false;last=null;};canvas.onpointerup=stop;canvas.onpointercancel=stop;canvas.onlostpointercapture=stop;
 $('#clearCanvas').onclick=()=>{points=[];distance=0;last=null;finished=false;redraw();feedback('Yeni bir deneme, yeni bir keşif!');};
 $('#checkTrace').onclick=()=>{
  if(finished)return;if(distance<70||points.length<10){feedback('Önce açık renkli harfin üzerinden biraz çizelim.','error');return;}
  const covered=new Set();let inside=0;
  for(const p of points){let near=false;for(let dy=-17;dy<=17;dy+=8)for(let dx=-17;dx<=17;dx+=8){const x=Math.round(p.x+dx),y=Math.round(p.y+dy);if(x<0||x>=w||y<0||y>=h)continue;if(md[(y*w+x)*4+3]>70){near=true;covered.add(`${Math.floor(x/12)},${Math.floor(y/12)}`);}}if(near)inside++;}
  const coverage=[...cells].filter(c=>covered.has(c)).length/Math.max(cells.size,1),precision=inside/points.length;
  if(coverage<.53||precision<.57){feedback(precision<.57?'Çizgilerimizi açık renkli harfin içinde tutmayı deneyelim.':'Çok güzel başladın! Harfin boş kalan yerlerinin üzerinden de geçelim.','error');return;}
  finished=true;award(currentExercise);feedback('Harika çaba! Harfi birlikte tamamladık. ★','success');speak(`Harika! ${glyph} harfini çizdin.`);const next=allLetters[(allLetters.indexOf(letter)+1)%allLetters.length];$('#checkTrace').innerHTML=`Sıradaki harf: ${next} ${icon('arrow')}`;$('#checkTrace').onclick=()=>openWrite(next);
 };
 modalCleanup=()=>{drawing=false;canvas.onpointerdown=null;canvas.onpointermove=null;};
}

const reading={
 syllable:[{parts:['E','L'],result:'EL',image:'🖐️'},{parts:['A','L'],result:'AL',image:'🤲'},{parts:['L','A'],result:'LA',image:'🎵'},{parts:['A','N'],result:'AN',image:'⏳'},{parts:['E','N'],result:'EN',image:'↔️'},{parts:['K','A'],result:'KA',image:'🦉'}],
 word:[{parts:['EL','MA'],result:'ELMA',image:'🍎'},{parts:['LA','LE'],result:'LALE',image:'🌷'},{parts:['AN','NE'],result:'ANNE',image:'👩'},{parts:['KA','LEM'],result:'KALEM',image:'✏️'},{parts:['MA','SA'],result:'MASA',image:'🪑'},{parts:['KE','Dİ'],result:'KEDİ',image:'🐱'}],
 sentence:[{parts:['Ali','top','at.'],result:'Ali top at.',image:'⚽'},{parts:['Ela','elma','al.'],result:'Ela elma al.',image:'🍎'},{parts:['Anne','lale','al.'],result:'Anne lale al.',image:'🌷'},{parts:['Ali','kalem','al.'],result:'Ali kalem al.',image:'✏️'}]
};
function shuffled(values){const a=[...values];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function openRead(type,index) {
 const list=reading[type],item=list[index],titles={syllable:'Harfleri birleştirelim',word:'Kelimeyi oluşturalım',sentence:'Cümlemizi kuralım'},kind={syllable:'heceyi',word:'kelimeyi',sentence:'cümleyi'};
 showActivity('02 · BİRLİKTE OKUYALIM',`<div class="activity-heading"><h2 id="activityTitle">${titles[type]}</h2><span class="mini-step">${index+1} / ${list.length}</span></div><p class="activity-sub">${type==='sentence'?'Kelimelere doğru sırayla dokun.':type==='word'?'Hecelere doğru sırayla dokun.':'Harflere doğru sırayla dokun.'} ${kind[type]} birlikte oluşturalım.</p><div class="centered"><span class="word-picture" aria-hidden="true">${item.image}</span><button class="secondary" id="hearTarget">${icon('sound')} ${type==='syllable'?'Heceyi':type==='word'?'Kelimeyi':'Cümleyi'} dinle</button><div class="slots" id="slots"></div><div class="token-bank" id="tokenBank"></div><div class="tool-row"><button class="secondary" id="resetRead">↺ Baştan kur</button><button class="primary" id="checkRead">Birlikte okuyalım ${icon('arrow')}</button></div><p class="feedback" id="feedback" role="status">İstersen önce dinleyebilirsin.</p></div>`);
 let chosen=[],finished=false;const bank=shuffled(item.parts.map((text,id)=>({text,id})));
 function paint(){ $('#slots').innerHTML=item.parts.map((_,i)=>`<button class="slot ${chosen[i]?'filled':''}" data-slot="${i}" aria-label="${i+1}. yer${chosen[i]?': '+escapeHTML(chosen[i].text)+', geri al':''}">${chosen[i]?escapeHTML(chosen[i].text):'·'}</button>`).join('');$('#tokenBank').innerHTML=bank.map(token=>`<button class="token" data-token="${token.id}" ${chosen.some(c=>c.id===token.id)||finished?'disabled':''}>${escapeHTML(token.text)}</button>`).join('');$$('[data-token]').forEach(b=>b.onclick=()=>{if(chosen.length<item.parts.length&&!finished){chosen.push(bank.find(t=>t.id===Number(b.dataset.token)));paint();}});$$('[data-slot]').forEach(b=>b.onclick=()=>{if(!finished&&chosen[+b.dataset.slot]){chosen.splice(+b.dataset.slot,1);paint();}}); }
 paint();$('#hearTarget').onclick=()=>speak(item.result,{force:true});$('#resetRead').onclick=()=>{if(finished){openRead(type,index);return;}chosen=[];paint();feedback('Yeniden birlikte deneyelim.');};
 $('#checkRead').onclick=()=>{if(chosen.length!==item.parts.length){feedback('Önce bütün boşlukları dolduralım.','error');return;}if(!chosen.every((t,i)=>t.text===item.parts[i])){feedback('Bir kez daha dinleyelim, sırayı birlikte bulabiliriz.','error');speak(item.result);return;}finished=true;award(`${type}:${index}`);paint();feedback(`Başardın! ${item.result} ★`,'success');speak(item.result);$('#checkRead').innerHTML=index<list.length-1?`Sıradaki oyun ${icon('arrow')}`:`Tamamladık! ${icon('star')}`;$('#checkRead').onclick=()=>index<list.length-1?openRead(type,index+1):completePanel('Birlikte çok güzel okuduk!','Harfler birleşti, yeni keşifler başladı. İstersen başka bir oyuna geçebiliriz.');};
}
const listening=[{word:'elma',emoji:'🍎'},{word:'kedi',emoji:'🐱'},{word:'top',emoji:'⚽'},{word:'lale',emoji:'🌷'},{word:'kalem',emoji:'✏️'},{word:'arı',emoji:'🐝'},{word:'balık',emoji:'🐟'},{word:'güneş',emoji:'☀️'}];
function openListen(index){
 const target=listening[index],options=shuffled([target,...shuffled(listening.filter(x=>x!==target)).slice(0,2)]);let heard=false,finished=false;
 showActivity('03 · DİNLE VE BUL',`<div class="activity-heading"><h2 id="activityTitle">Hangi kelimeyi duydun?</h2><span class="mini-step">${index+1} / ${listening.length}</span></div><p class="activity-sub">Önce ses düğmesine dokun. Sonra duyduğun kelimenin resmini seç.</p><div class="centered"><button class="listen-big" id="playWord" aria-label="Gizli kelimeyi dinle">${icon('sound')}</button><p class="small-help" id="audioHint">Hazırsan dinleyelim.</p><div class="listen-options">${options.map(o=>`<button class="listen-choice" data-answer="${o.word}"><span aria-hidden="true">${o.emoji}</span><b>${o.word}</b></button>`).join('')}</div><p class="feedback" id="feedback" role="status">Sesini dilediğin kadar tekrar dinleyebilirsin.</p><button class="primary" id="nextListen" hidden>Yeni ses ${icon('arrow')}</button></div>`);
 $('#playWord').onclick=()=>{heard=speak(target.word,{force:true});if(heard)$('#audioHint').textContent='Dinle, düşün, resmini bul.';else $('#audioHint').textContent=`Ses desteği yok. Görsel eşleştirme için şu kelimeyi bul: ${target.word}`;};
 $$('[data-answer]').forEach(b=>b.onclick=()=>{if(finished)return;if(!heard&&'speechSynthesis'in window){feedback('Önce büyük ses düğmesine dokunalım.','error');return;}if(b.dataset.answer!==target.word){b.classList.add('incorrect');feedback('Bir daha dinleyelim. Yeniden deneyebilirsin.','error');if(heard)speak(target.word,{force:true});return;}finished=true;b.classList.add('correct');award(`listen:${index}`);feedback(`Evet, ${target.word}! Çok dikkatli dinledin. ★`,'success');speak(`Evet, ${target.word}!`);$('#nextListen').hidden=false;$('#nextListen').onclick=()=>index<listening.length-1?openListen(index+1):completePanel('Kulaklarına sağlık!','Bütün kelimeleri keşfettin. Şimdi biraz çizelim mi?');});
}
function completePanel(title,desc){showActivity('✦ KEŞİF TAMAMLANDI',`<div class="complete-panel">${owl('success-owl')}<h2 id="activityTitle">${title}</h2><p>${desc}</p><button class="primary" id="backToHome">Keşif alanıma dön ${icon('arrow')}</button></div>`);$('#backToHome').onclick=()=>{closeActivity();navigate('home');};}
function openSpeak(index){
 const item=listening[index],Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 showActivity('03 · DİNLE VE SÖYLE',`<div class="activity-heading"><h2 id="activityTitle">Şimdi sıra sende!</h2><span class="mini-step">${index+1} / ${listening.length}</span></div><p class="activity-sub">Kelimeyi dinle. Sonra sen de yüksek sesle söyle.</p><div class="centered"><span class="word-picture" aria-hidden="true">${item.emoji}</span><div class="speak-word">${item.word}</div><button class="secondary" id="modelWord">${icon('sound')} Önce dinleyelim</button><div style="margin-top:25px"><button class="mic-button" id="startMic">${icon('mic')} Ben de söyleyeyim</button></div><p class="feedback" id="feedback" role="status"></p><button class="secondary" id="practiceTogether" style="margin-top:12px">Bir büyüğümle söyledim ✓</button><p class="small-help">Ses tanıma her zaman doğru duymayabilir. Bu oyun bir telaffuz değerlendirmesi değildir.</p></div>`);
 let busy=false,done=false;$('#modelWord').onclick=()=>speak(item.word,{force:true});
 const success=()=>{if(done)return;done=true;award(`speak:${index}`);feedback('Birlikte söylemek çok güzel! Harika bir çaba. ★','success');$('#startMic').disabled=true;$('#practiceTogether').textContent='Sıradaki kelime →';$('#practiceTogether').onclick=()=>index<listening.length-1?openSpeak(index+1):completePanel('Sesinle yeni keşifler yaptın!','İster dinleyerek, ister söyleyerek… Her deneme çok değerli.');};
 $('#practiceTogether').onclick=success;
 if(!Recognition)feedback('Bu tarayıcı ses tanımayı desteklemiyor. Bir büyüğünle kelimeyi söyleyip alttaki düğmeyle devam edebilirsin.');
 $('#startMic').onclick=()=>{
  if(!Recognition){feedback('Mikrofonla tanıma bu tarayıcıda yok. Bir büyüğünle birlikte söyleyelim.','error');return;}
  if(!micAllowed){feedback('Mikrofon için önce bir büyüğün ebeveyn alanından bu oturuma izin versin.','error');const parentLink=document.createElement('button');parentLink.className='secondary';parentLink.textContent='Ebeveyn alanını aç';parentLink.onclick=()=>{closeActivity();openParent();};$('#feedback').append(document.createElement('br'),parentLink);return;}
  if(busy)return;busy=true;if('speechSynthesis'in window)speechSynthesis.cancel();const r=new Recognition();recognition=r;r.lang='tr-TR';r.interimResults=false;r.maxAlternatives=3;
  $('#startMic').classList.add('recording');$('#startMic').innerHTML=`${icon('mic')} Seni dinliyorum…`;feedback('Kelimeyi söyle.');
  r.onresult=e=>{const texts=Array.from(e.results[0],x=>x.transcript.toLocaleLowerCase('tr-TR').replace(/[^a-zçğıöşü]/g,''));if(texts.includes(item.word)){success();}else feedback(`“${e.results[0][0].transcript}” duydum. İstersen tekrar deneyelim; ses tanıma bazen yanılabilir.`);};
  r.onerror=e=>feedback(e.error==='not-allowed'?'Mikrofon izni verilmedi. Tarayıcı ayarlarını bir büyüğünle kontrol edebilirsin.':'Sesini anlayamadım. Tekrar deneyebilir veya bir büyüğünle söyleyebilirsin.','error');
  r.onend=()=>{busy=false;const b=$('#startMic');if(b){b.classList.remove('recording');b.innerHTML=`${icon('mic')} ${done?'Birlikte söyledik':'Yeniden söyleyeyim'}`;}};
  try{r.start();}catch{busy=false;$('#startMic').classList.remove('recording');feedback('Mikrofon başlatılamadı. Bir büyüğünle devam edebilirsin.','error');}
 };
}

function openParent(){if(!$('#parent').open)$('#parent').showModal();if(parentVerified){parentDashboard();return;}$('#parentBody').innerHTML=`<h2 id="parentTitle">Merhaba, sevgili ebeveyn.</h2><p class="activity-sub">Birlikte büyüyen bu yolculuğa göz atalım. Bu alanı bir yetişkinle açalım.</p><label class="parent-field" for="parentAnswer">7 + 5 kaç eder?</label><input id="parentAnswer" inputmode="numeric" autocomplete="off" placeholder="Yanıtı buraya yazın"><p id="gateFeedback" class="feedback" role="status"></p><button class="primary" id="unlockParent">Ebeveyn alanını aç ${icon('arrow')}</button><p class="small-help">Bu, yetişkin eşliğini teşvik eden basit bir geçiştir; hesap güvenliği sağlamaz.</p>`;$('#unlockParent').onclick=()=>{if($('#parentAnswer').value.trim()!=='12'){$('#gateFeedback').textContent='Bir kez daha deneyin.';return;}parentVerified=true;parentDashboard();};$('#parentAnswer').onkeydown=e=>{if(e.key==='Enter')$('#unlockParent').click();};}
function parentDashboard(){const completed=state.completed;$('#parentBody').innerHTML=`<h2 id="parentTitle">Her adımı değerli.</h2><p class="activity-sub">Novarge · Ebeveyn alanı</p><div class="parent-stats"><div class="parent-stat"><b>${tracedLetters().length}</b><span>Çizilen büyük harf</span></div><div class="parent-stat"><b>${completed.length}</b><span>Farklı etkinlik</span></div><div class="parent-stat"><b>${todayCount()}</b><span>Bugünkü oyun</span></div></div><label class="parent-field" for="childName">Ekranda görünen takma ad</label><input id="childName" maxlength="22" value="${escapeHTML(state.name)}"><label class="parent-field" for="dailyGoal">Günlük küçük hedef</label><select id="dailyGoal"><option value="2">2 oyun · Rahat bir başlangıç</option><option value="3">3 oyun · Küçük keşifler</option><option value="5">5 oyun · Biraz daha keşif</option></select><label class="parent-field" style="display:flex;align-items:flex-start;gap:10px;line-height:1.8;font-weight:500"><input id="allowMic" type="checkbox" ${micAllowed?'checked':''} style="width:18px;margin-top:4px">Bu oturumda mikrofonla kelime tanımayı aç. Konuşma, tarayıcının ses tanıma hizmetine gönderilebilir. Uygulama ses kaydı saklamaz.</label><div class="parent-actions"><button class="primary" id="saveParent">Ayarları kaydet ${icon('check')}</button><button class="secondary" id="exportProgress">İlerlemeyi indir</button></div><p class="parent-note">İlerleme yalnızca bu tarayıcıda tutulur; farklı cihazlarla eşitlenmez. ${storageAvailable?'Tarayıcı verilerini silmek ilerlemeyi de siler.':'Bu tarayıcıda kalıcı kayıt kullanılamıyor.'}<br><b>Öğrenme yaklaşımı:</b> Etkinlikleri çocuğun isteğine ve hazır oluşuna göre kısa tutun. Sesli harf örnekleri cihazın Türkçe seslendirmesinden gelir; öğretmen tarafından kaydedilmiş harf sesleri bu prototipte bulunmaz. Otomatik çizim ve kelime eşleştirme, gelişim veya telaffuz ölçümü değildir.<br><b>Bu sürüm:</b> Etkileşimli prototip. Yapay zekâ öğretmeni, uzman onaylı tam müfredat ve hesaplar henüz bağlı değildir.</p><button class="secondary danger" id="resetProgress">Bu cihazdaki ilerlemeyi sıfırla</button><div id="resetConfirm"></div>`;
 $('#dailyGoal').value=String(state.dailyGoal);
 $('#saveParent').onclick=()=>{state.name=$('#childName').value.trim()||'Minik kaşif';state.dailyGoal=Number($('#dailyGoal').value);micAllowed=$('#allowMic').checked;save();$('#parent').close();render();toast('Ayarlar kaydedildi. Güzel keşifler!');};
 $('#exportProgress').onclick=()=>{const data={uygulama:'Novarge Okuma Yazma',tarih:new Date().toISOString(),takmaAd:state.name,tamamlananEtkinlikler:state.completed,oyunGecmisi:state.activityLog};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='novarge-ilerleme.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('#resetProgress').onclick=()=>{$('#resetConfirm').innerHTML='<p class="parent-note">Bu tarayıcıdaki yıldızlar ve etkinlik geçmişi silinecek. Önce ilerlemeyi indirebilirsiniz.</p><button class="secondary danger" id="confirmReset">Evet, ilerlemeyi sil</button>';$('#confirmReset').onclick=()=>{state=fresh();micAllowed=false;save();parentDashboard();render();toast('İlerleme sıfırlandı. Yeni bir yolculuğa hazırız.');};};
}
$('#parentBtn').onclick=openParent;$('#profileBtn').onclick=openParent;$('#closeParent').onclick=()=>$('#parent').close();
const initial=location.hash.slice(1);if(['home','write','read','listen','rewards'].includes(initial))page=initial;render();
